/**
 * Shared material palette — created once, reused by every builder.
 *
 * Textures are painted on <canvas> at start-up (no image files). Materials that
 * carry `userData.worldUV` get their UVs regenerated by GeometryBatch from
 * world position (in inches), so a texture tile has a fixed physical size:
 *  - siding: 18" x 18" tile = four 4.5" laps
 *  - brick:  33.5" x 21.3" tile = 4 bricks x 8 courses
 */
import * as THREE from 'three';

/** Small deterministic PRNG so textures are identical on every load. */
function mulberry32(seed: number): () => number {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function canvasTexture(w: number, h: number, paint: (g: CanvasRenderingContext2D) => void): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const g = canvas.getContext('2d');
  if (!g) throw new Error('2D canvas unavailable');
  paint(g);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 8;
  return tex;
}

/** Horizontal lap siding; 4 laps per tile, each with a soft shadow line at its lower edge. */
function sidingTexture(): THREE.CanvasTexture {
  const tex = canvasTexture(256, 256, (g) => {
    const lap = 64;
    for (let i = 0; i < 4; i++) {
      const y = i * lap;
      const grad = g.createLinearGradient(0, y, 0, y + lap);
      grad.addColorStop(0, '#fbfbf8');
      grad.addColorStop(0.82, '#f1f1ec');
      grad.addColorStop(1, '#d9d9d3');
      g.fillStyle = grad;
      g.fillRect(0, y, 256, lap);
      g.fillStyle = 'rgba(70,70,60,0.28)'; // shadow line under the lap
      g.fillRect(0, y + lap - 3, 256, 2);
      g.fillStyle = 'rgba(255,255,255,0.7)'; // lit upper edge of the next lap
      g.fillRect(0, y, 256, 1);
    }
  });
  tex.repeat.set(1 / 18, 1 / 18);
  return tex;
}

/** Red brick in running bond, with per-brick tint variation. */
function brickTexture(): THREE.CanvasTexture {
  const tex = canvasTexture(512, 320, (g) => {
    const rnd = mulberry32(7);
    g.fillStyle = '#cfc6b8';
    g.fillRect(0, 0, 512, 320);
    const rows = 8, rowH = 40, brickW = 128, gap = 5;
    for (let r = 0; r < rows; r++) {
      const off = r % 2 ? brickW / 2 : 0;
      for (let c = -1; c < 5; c++) {
        const x = c * brickW + off;
        const l = 38 + rnd() * 10, s = 42 + rnd() * 14, h = 8 + rnd() * 8;
        g.fillStyle = `hsl(${h} ${s}% ${l}%)`;
        g.fillRect(x + gap / 2, r * rowH + gap / 2, brickW - gap, rowH - gap);
      }
    }
  });
  tex.repeat.set(1 / 33.5, 1 / 21.33);
  return tex;
}

/** Faint mottling for the lawn so the ground does not read as a flat colour. */
function grassTexture(): THREE.CanvasTexture {
  const tex = canvasTexture(128, 128, (g) => {
    const rnd = mulberry32(21);
    g.fillStyle = '#8fa078';
    g.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 1400; i++) {
      g.fillStyle = `rgba(${60 + rnd() * 40},${80 + rnd() * 50},${50 + rnd() * 30},0.18)`;
      g.fillRect(rnd() * 128, rnd() * 128, 2 + rnd() * 3, 2 + rnd() * 3);
    }
  });
  tex.repeat.set(1 / 240, 1 / 240); // one tile per 20 ft (UV is in inches)
  return tex;
}

export interface Materials {
  siding: THREE.MeshStandardMaterial;
  trim: THREE.MeshStandardMaterial;
  sash: THREE.MeshStandardMaterial;
  glass: THREE.MeshPhysicalMaterial;
  door: THREE.MeshStandardMaterial;
  brick: THREE.MeshStandardMaterial;
  roof: THREE.MeshStandardMaterial;
  interior: THREE.MeshStandardMaterial;
  floor: THREE.MeshStandardMaterial;
  concrete: THREE.MeshStandardMaterial;
  cabinet: THREE.MeshStandardMaterial;
  soapstone: THREE.MeshStandardMaterial;
  porcelain: THREE.MeshStandardMaterial;
  appliance: THREE.MeshStandardMaterial;
  wood: THREE.MeshStandardMaterial;
  ground: THREE.MeshStandardMaterial;
  railing: THREE.MeshStandardMaterial;
}

/** Marks a material so GeometryBatch regenerates world-space UVs for it. */
function worldUV<T extends THREE.Material>(m: T): T {
  m.userData.worldUV = true;
  return m;
}

function createMaterials(): Materials {
  const std = (color: string, roughness = 0.8, metalness = 0, extra: THREE.MeshStandardMaterialParameters = {}) =>
    new THREE.MeshStandardMaterial({ color, roughness, metalness, ...extra });
  return {
    siding: worldUV(std('#ffffff', 0.85, 0, { map: sidingTexture() })),
    trim: std('#f7f7f3', 0.6),
    sash: std('#8a948a', 0.55),
    glass: new THREE.MeshPhysicalMaterial({
      color: '#1d2a36', roughness: 0.06, metalness: 0.1, clearcoat: 1, clearcoatRoughness: 0.05, envMapIntensity: 1.4,
    }),
    door: std('#8c5128', 0.45),
    brick: worldUV(std('#ffffff', 0.9, 0, { map: brickTexture() })),
    roof: std('#4a4f55', 0.45, 0.6, { side: THREE.DoubleSide }),
    interior: std('#efe6d6', 0.9),
    floor: std('#c79a62', 0.7),
    concrete: std('#9a9c9a', 0.95),
    cabinet: std('#a9b4a8', 0.55),
    soapstone: std('#3d4043', 0.5),
    porcelain: std('#f4f6f6', 0.3),
    appliance: std('#b9bec2', 0.35, 0.6),
    wood: std('#a87c4e', 0.7),
    ground: worldUV(std('#ffffff', 1, 0, { map: grassTexture() })),
    railing: std('#f2f2ee', 0.6),
  };
}

/** The one palette instance. */
export const materials: Materials = createMaterials();
